#!/usr/bin/env python3
"""r2-ch15c — prose, pointer and cross-volume claims of Chapter 26 (main L7117-L7202).

Chat 104.  Reads the six volume MEMBERS, never a bundle.  Resolvers imported from r2lib by path
and passed the LINE LIST.  Every pointer test carries a claim-locator beside it: a token test that
fails names no target, so each failure is followed by a sweep for where the claim actually lives.
Matches print a WINDOW around the hit, never the head of the line - these lines run past 300 chars.
"""
import importlib.util, re

H = '/home/claude/members/'
spec = importlib.util.spec_from_file_location('r2lib', H + 'r2lib.py')
r2lib = importlib.util.module_from_spec(spec); spec.loader.exec_module(r2lib)
from r2lib import heading_line, section_span, has_token, enclosing

VOL = {'main': 'The_Method_1_6-2.md',
       'reg':  'The_Method_1_6___The_Register-2.md',
       'mc':   'The_Method_1_6___Mathematical_Compendium-2.md',
       'pc':   'The_Method_1_6___The_Physics_Compendium-2.md',
       'ioi':  'The_Method_1_6___The_Index_of_Indices-2.md',
       'sc':   'The_Method_1_6___Spectra_Compendium-2.md'}
M = {k: r2lib.read_member(v).split('\n') for k, v in VOL.items()}
A, B = 7117, 7202

def head(s): print('\n== ' + s)

def win(line, tok, w=70):
    """A window around the first match, not the head of the line (chat 103's fault 2)."""
    i = line.lower().find(tok.lower())
    if i < 0: return line[:2*w]
    return ('...' if i-w > 0 else '') + line[max(0, i-w):i+len(tok)+w] + ('...' if i+len(tok)+w < len(line) else '')

def sweep(tok, vols=None, limit=8, label=None):
    """Word-bounded, case-insensitive, on the RAW line, across the named volumes."""
    out = {}
    for k in (vols or VOL):
        hits = [(i+1, l) for i, l in enumerate(M[k]) if has_token(l, tok)]
        out[k] = hits
    tot = sum(len(v) for v in out.values())
    print(f'   {label or tok!r:<34} total {tot:>4} :', ', '.join(f'{k} {len(v)}' for k, v in out.items()))
    return out

print('r2-ch15c  Chapter 26, main L%d-L%d' % (A, B))

# ---------------------------------------------------------------- C1 pointers out of the chapter
head('C1  the two section pointers the chapter makes, each with a claim-locator')

print('  L7156 -> 29.8, for "the searched bound"')
sp = section_span(M['main'], '29.8')
print('   heading_line(29.8) =', heading_line(M['main'], '29.8'), '| span =', sp)
if sp:
    body = '\n'.join(M['main'][sp[0]-1:sp[1]-1])
    print('   heading text:', M['main'][sp[0]-1].strip())
    for t in ('searched', 'bound', 'search', 'C6', 'collective', '0.0'):
        print(f'     token {t!r:<12} in 29.8: {has_token(body, t)}')
    for i in range(sp[0]-1, min(sp[1]-1, sp[0]+9)):
        if M['main'][i].strip(): print('     |', M['main'][i].strip()[:150])
print('   CLAIM-LOCATOR - where does "searched bound" actually live?')
for k in VOL:
    for i, l in enumerate(M[k]):
        if 'searched bound' in l.lower():
            print(f'     {k} L{i+1}: {win(l, "searched bound")}')

print('\n  L7185 -> 23.11, for "exactly lambda^2 of 23.11"')
sp = section_span(M['main'], '23.11')
print('   heading_line(23.11) =', heading_line(M['main'], '23.11'), '| span =', sp)
if sp:
    body = '\n'.join(M['main'][sp[0]-1:sp[1]-1])
    print('   heading text:', M['main'][sp[0]-1].strip())
    for t in ('lambda', 'Newton', 'decrease'):
        print(f'     token {t!r:<10} in 23.11: {has_token(body, t)}')
    print('     literal "λ" count in 23.11:', body.count('λ'), '| "λ²" count:', body.count('λ²'),
          '| "2/3" count:', body.count('2/3'))
    for i in range(sp[0]-1, sp[1]-1):
        if 'λ' in M['main'][i]:
            print(f'     L{i+1}: {win(M["main"][i], "λ")}')

# ---------------------------------------------------------------- C2 attributions
head('C2  attributions in the chapter, against the bibliography (docket 16 class)')
for name in ('Singer', 'Aitken'):
    hits = sweep(name, label=f'{name!r} across six volumes')
    for k, v in hits.items():
        for ln, l in v[:4]:
            print(f'      {k} L{ln}: {win(l, name, 60)}')
print('   name-form check on the chapter line itself:')
print('    ', M['main'][7162].strip()[:170])

# ---------------------------------------------------------------- C3 absent-member (docket 20)
head('C3  Rb: the chapter prices a route on Rb ns-ns (L7163). Does Rb have a channel row?')
rows = [(i+1, l) for i, l in enumerate(M['sc']) if re.match(r'^\|\s*Rb\b', l.strip())]
print('   spectra-member rows beginning "| Rb":', len(rows))
for ln, l in rows[:6]: print(f'     L{ln}: {l.strip()[:150]}')
allrb = sweep('Rb', label="'Rb' across six volumes")
for k, v in allrb.items():
    for ln, l in v[:3]:
        print(f'      {k} L{ln}: {win(l, "Rb", 55)}')
print('   rubidium (spelled out):')
sweep('rubidium', label="'rubidium'")

# ---------------------------------------------------------------- C4 Ruling 45 / 46 sweep
head('C4  Ruling 45 (no build or editorial-process remarks) and Ruling 46 (no internals)')
CH = M['main'][A-1:B]
R45 = ('reader', 'referee', 'author', 'we ', 'I ', 'chapter', 'this book', 'written',
       'stated rather', 'discovered')
for t in R45:
    n = sum(1 for l in CH if has_token(l, t.strip()))
    if n: print(f'   {t!r:<16} {n:>2} in the chapter')
print('   the two candidate lines, printed in full:')
for ln in (7189, 7190, 7201, 7192):
    print(f'     L{ln}: {M["main"][ln-1].strip()}')
R46 = ('build', 'py', 'script', 'BUILD', 'md5', 'instrument')
print('   Ruling 46 tokens:', ', '.join(f'{t}={sum(1 for l in CH if has_token(l, t))}' for t in R46))

# ---------------------------------------------------------------- C5 false universals (docket 19)
head('C5  false-universal class (docket 19): every / all / never in the chapter')
for i, l in enumerate(M['main'][A-1:B], A):
    for t in ('every', 'all', 'never', 'always', 'no '):
        if has_token(l, t.strip()):
            print(f'   L{i} [{t.strip()}]: {win(l, t.strip(), 75)}'); break

# ---------------------------------------------------------------- C6 heading sentences (14q-06)
head('C6  do any of the seven headings finish in the body? (14q-06 class)')
for ln in (7117, 7119, 7141, 7149, 7153, 7162, 7172, 7194):
    nxt = next((M['main'][j] for j in range(ln, min(ln+3, len(M['main']))) if M['main'][j].strip()), '')
    print(f'   L{ln} {M["main"][ln-1].strip()[:62]:<62} -> body opens: {nxt.strip()[:55]}')

# ---------------------------------------------------------------- C7 the splice-corruption class
head('C7  the L7156 splice: sweep both the volume and the Prints & Proofs original for the shape')
PAT = re.compile(r'\d\.\d*(?=[a-z]{3})')          # a number running straight into a lowercase word
for k in VOL:
    hits = [(i+1, l) for i, l in enumerate(M[k]) if PAT.search(l)]
    print(f'   {k:<5} lines where a decimal runs into a word: {len(hits)}')
    for ln, l in hits[:6]:
        print(f'      L{ln}: {win(l, PAT.search(l).group(0), 70)}')
print('   the same phrase, elsewhere in the main volume:')
for i, l in enumerate(M['main']):
    if 'searched bound' in l.lower() or re.search(r'\bbracketing rather than\b', l):
        print(f'     L{i+1}: {win(l, "searched bound" if "searched bound" in l.lower() else "bracketing rather than", 60)}')

# ---------------------------------------------------------------- C8 figure numbering
head('C8  Figure 26.1: the Prints & Proofs original captions it "Figure 19.1"')
for tag in ('Figure 26.1', 'Figure 19.1', 'figure-26.1', 'figure-19.1'):
    tot = 0
    for k in VOL:
        n = sum(1 for l in M[k] if tag.lower() in l.lower())
        tot += n
        if n: print(f'   {tag!r:<14} {k}: {n}')
    if not tot: print(f'   {tag!r:<14} 0 sites in six volumes')

# ---------------------------------------------------------------- C9 claim-locators for B3/B12/B13
head('C9  claim-locators for the figures the computable batch could not reproduce')
for tok, lab in (('fifteen', 'the fifteen quantities'), ('cost law', 'the cost law'),
                 ('three-level', 'the three-level bracket'), ('66', '"66 of 66"'),
                 ('9.49', 'sigma_1'), ('1.05', 'median error'), ('1.83', 'maximum error')):
    print(f'  {lab}:')
    for k in VOL:
        hits = [(i+1, l) for i, l in enumerate(M[k]) if (tok.lower() in l.lower() if ' ' in tok or tok.isdigit() or '.' in tok else has_token(l, tok))]
        if hits:
            print(f'     {k}: {len(hits)} site(s)', end='')
            print(' ->', ', '.join(f'L{ln}' for ln, _ in hits[:6]))
            for ln, l in hits[:2]:
                if not (A <= ln <= B and k == 'main'):
                    print(f'        L{ln}: {win(l, tok, 60)}')

print('\nr2-ch15c complete')

