# ---------------------------------------------------------------- C7 the splice-corruption class
head('C7  the L7156 splice: sweep both the volume and the Prints & Proofs original for the shape')
PAT = re.compile(r'\d\.\d*(?=[a-z]{3})')          # a number running straight into a lowercase word
for k in VOL:
    hits = [(i+1, l) for i, l in enumerate(M[k]) if PAT.search(l)]
    print(f'   {k:<5} lines where a decimal runs into a word: {len(hits)}')
    for ln, l in hits[:6]:
        print(f'      L{ln}: {win(l, PAT.search(l).group(0), 70)}')
print('   the same phrase, elsewhere in the main volume:')
for i, l in enumerate(M['main']):
    if 'searched bound' in l.lower() or re.search(r'\bbracketing rather than\b', l):
        print(f'     L{i+1}: {win(l, "searched bound" if "searched bound" in l.lower() else "bracketing rather than", 60)}')

